<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\Competition;use Illuminate\Http\Request;use Illuminate\Support\Str;class CompetitionController extends Controller{public function index(){return view('admin.competitions.index',['items'=>Competition::latest('starts_at')->paginate(30)]);}public function create(){return view('admin.competitions.form',['item'=>new Competition]);}public function store(Request $r){Competition::create($this->data($r));return redirect()->route('admin.competitions.index')->with('ok','Событие добавлено');}public function edit(Competition $competition){return view('admin.competitions.form',['item'=>$competition]);}public function update(Request $r,Competition $competition){$competition->update($this->data($r));return redirect()->route('admin.competitions.index')->with('ok','Сохранено');}public function destroy(Competition $competition){$competition->delete();return back();}private function data(Request $r){$d=$r->validate(['title'=>'required|max:255','kind'=>'required|in:competition,festival','description'=>'nullable','place'=>'nullable|max:255','starts_at'=>'nullable|date','ends_at'=>'nullable|date','image'=>'nullable|image|max:10240','document'=>'nullable|file|max:20480|mimes:pdf,doc,docx']);$d['slug']=Str::slug($r->input('slug')?:$d['title']);if($r->hasFile('image'))$d['image']=$r->file('image')->store('competitions','public');if($r->hasFile('document'))$d['document']=$r->file('document')->store('competitions/documents','public');$d['is_published']=$r->boolean('is_published');return $d;}}